class Solution {
public:
    int longestSubsequence(std::string s, int k) {
        long long val = 0;
        int cnt = 0, pos = 0;
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            if (s[i] == '0') {
                cnt++;
            } else if (pos < 31 && val + (1LL << pos) <= k) {
                val += (1LL << pos);
                cnt++;
            }
            pos++;
        }
        return cnt;
    }
};

class Solution {
    public int longestSubsequence(String s, int k) {
        long val = 0;
        int cnt = 0, pos = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == '0') {
                cnt++;
            } else if (pos < 31 && val + (1L << pos) <= k) {
                val += (1L << pos);
                cnt++;
            }
            pos++;
        }
        return cnt;
    }
}

var longestSubsequence = function(s, k) {
    let val = 0;
    let cnt = 0, pos = 0;
    for (let i = s.length - 1; i >= 0; i--) {
        if (s[i] === '0') {
            cnt++;
        } else if (pos < 31 && val + (1 << pos) <= k) {
            val += (1 << pos);
            cnt++;
        }
        pos++;
    }
    return cnt;
};
